package com.wizzadrds.theworldremembers.chronicle; import java.util.*; public record ChronicleBook(List<ChronicleEntry> timeline,List<String> people,List<String> relationships,List<String> families,List<String> villages){public ChronicleBook{timeline=List.copyOf(timeline);people=List.copyOf(people);relationships=List.copyOf(relationships);families=List.copyOf(families);villages=List.copyOf(villages);}}